        main(()->{titles.detail(RpgGrowthFacts.entry(earned.get(0)),true);titles.dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});loaded(titles);check(RpgProgressStore.progress(c).optString("equipped_title").equals(earned.get(0)),"Explicit dialog button equips");
        main(()->{check(titles.current.getText().toString().equals(RpgGrowthUi.title(titles,earned.get(0))),"Current title emphasized");capture(titles.list,411,760,"title-wardrobe.png");titles.status=3;titles.refresh(true);for(RpgCollectionActivity.Row row:titles.adapter.rows)check(!RpgCollectionFacts.earned(titles.state,row.entry),"Locked titles separated");titles.equip("");});loaded(titles);check(RpgProgressStore.progress(c).optString("equipped_title").isEmpty(),"Unequip persists");
        main(()->{Configuration originalConfig=new Configuration(titles.getResources().getConfiguration());try{for(int width:new int[]{320,411,700})for(float scale:new float[]{1,1.5f}){Configuration conf=new Configuration(originalConfig);conf.screenWidthDp=width;conf.fontScale=scale;conf.setLocale(Locale.KOREAN);titles.getResources().updateConfiguration(conf,titles.getResources().getDisplayMetrics());titles.initialized=false;titles.header=titles.buildHeader();titles.adapter=titles.new MedalAdapter();titles.list.setAdapter(titles.adapter);titles.layout.setSpanCount(1);titles.status=1;titles.initialized=true;titles.refresh(true);capture(titles.list,width,760,"wardrobe-"+width+"-"+scale+".png");}}finally{titles.getResources().updateConfiguration(originalConfig,titles.getResources().getDisplayMetrics());}titles.finish();});
        RpgCollectionActivity small=open("achievements");main(()->{Configuration originalConfig=new Configuration(small.getResources().getConfiguration());try{for(int width:new int[]{320,411,700})for(float scale:new float[]{1,1.5f})for(boolean dark:new boolean[]{true,false}){Configuration conf=new Configuration(originalConfig);conf.screenWidthDp=width;conf.fontScale=scale;conf.setLocale(Locale.KOREAN);small.getResources().updateConfiguration(conf,small.getResources().getDisplayMetrics());small.dark=dark;small.initialized=false;small.header=small.buildHeader();small.adapter=small.new MedalAdapter();small.layout.setSpanCount(scale>1.25f?1:2);small.list.setAdapter(small.adapter);small.status=0;small.initialized=true;small.refresh(true);capture(small.list,width,760,"codex-"+width+"-"+scale+"-"+dark+".png");check(small.layout.getSpanCount()==(scale>1.25f?1:2),"Adaptive grid font policy");}}finally{small.getResources().updateConfiguration(originalConfig,small.getResources().getDisplayMetrics());}});
        main(()->{small.state=null;small.status=0;small.refresh(true);check(small.adapter.rows.size()==53,"Empty state retains catalog goals");capture(small.list,411,760,"codex-empty.png");});
        SecureTokenStore.save(c,new AuthTokens("MEDAL_QA_OTHER","MEDAL_QA_OTHER_REFRESH","",now+86400000,"medal-other-synthetic-account",""));main(()->{check(!small.valid(),"Changed account rejects stale actions");small.clearAccount();check(small.state==null&&small.draft.isEmpty(),"Foreign account clears old presentation");small.finish();});SecureTokenStore.save(c,auth);
        JSONObject after=RpgProgressStore.export(c,account).getJSONObject("rpg");check(after.getLong("xp")==xp,"No extra XP from UI");check(after.getJSONObject("achievements").toString().equals(achievements),"All progress and acquisition dates unchanged");check(after.optJSONObject("KR").toString().equals(original.optJSONObject("KR").toString())&&after.optJSONObject("WORLD").toString().equals(original.optJSONObject("WORLD").toString()),"Tier records preserved");
