    void capture(View view,int width,int height,String name){try{int w=Ui.dp(c,width),h=Ui.dp(c,height);view.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));view.layout(0,0,w,h);Bitmap bitmap=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(view.getContext() instanceof RpgCollectionActivity?Ui.background(view.getContext(),((RpgCollectionActivity)view.getContext()).dark):0xff0d0e10);view.draw(canvas);File dir=new File(c.getExternalFilesDir(null),"rpg3-fixtures");dir.mkdirs();try(FileOutputStream file=new FileOutputStream(new File(dir,name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,file);}bitmap.recycle();}catch(Exception e){throw new RuntimeException(e);}}
    void sheet(RpgCollectionActivity a){LinearLayout grid=new LinearLayout(a);grid.setOrientation(LinearLayout.VERTICAL);for(int row=0;row<9;row++){LinearLayout line=new LinearLayout(a);for(int col=0;col<6;col++){int index=row*6+col;if(index<53)line.addView(RpgMedalUi.icon(a,RpgCatalog.ALL.get(index),true,64));}grid.addView(line);}capture(grid,411,620,"all-53-medals.png");}
